CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TYPE scope_environment AS ENUM ('INTERNAL','PUBLIC');
CREATE TYPE normalized_status AS ENUM ('HEALTHY','INFORMATIONAL','ATTENTION','WARNING','CRITICAL','INCONCLUSIVE');
CREATE TYPE confidence_level AS ENUM ('HIGH','MEDIUM','LOW');
CREATE TYPE module_risk_class AS ENUM ('PASSIVE','SAFE_ACTIVE','CONTROLLED_ACTIVE');
CREATE TYPE job_status AS ENUM ('PENDING','QUEUED','ASSIGNED','RUNNING','SUCCEEDED','FAILED','CANCELLED','TIMED_OUT','REJECTED');

CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, timezone text NOT NULL DEFAULT 'UTC', require_mfa boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, email text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), disabled_at timestamptz, UNIQUE(organization_id,email));
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES organizations(id), name text NOT NULL, system boolean NOT NULL DEFAULT false, UNIQUE(organization_id,name));
CREATE TABLE permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE role_permissions (role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,role_id));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), ip_hash text, user_agent_hash text);
CREATE INDEX sessions_active_user_idx ON sessions(organization_id,user_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE mfa_configurations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE UNIQUE, encrypted_totp_secret bytea NOT NULL, enabled boolean NOT NULL DEFAULT false, recovery_code_hashes text[] NOT NULL DEFAULT '{}', verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mfa_login_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE authorized_scopes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), type text NOT NULL CHECK(type IN ('HOSTNAME','IP','CIDR','URL')), value text NOT NULL, environment scope_environment NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','VERIFIED','APPROVED','REVOKED','EXPIRED')), verification_type text, verified_at timestamptz, verified_by uuid REFERENCES users(id), valid_from timestamptz NOT NULL, valid_until timestamptz NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CHECK(valid_until > valid_from), UNIQUE(organization_id,type,value));
CREATE INDEX authorized_scopes_active_idx ON authorized_scopes(organization_id,status,valid_until);
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, type text NOT NULL CHECK(type IN ('HOST','SERVER','WORKSTATION','NETWORK_DEVICE','SERVICE','DOMAIN','URL','OTHER')), hostname text, ip_address inet, environment scope_environment NOT NULL, criticality text NOT NULL CHECK(criticality IN ('LOW','MEDIUM','HIGH','CRITICAL')), owner text, description text, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), status normalized_status NOT NULL DEFAULT 'INFORMATIONAL', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX assets_org_last_seen_idx ON assets(organization_id,last_seen_at DESC);

CREATE TABLE agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, hostname text NOT NULL, os text NOT NULL, arch text NOT NULL, version text NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','ONLINE','DEGRADED','OFFLINE','REVOKED')), last_seen_at timestamptz, registered_at timestamptz NOT NULL DEFAULT now(), capabilities jsonb NOT NULL DEFAULT '[]', labels jsonb NOT NULL DEFAULT '{}', network_zone text, identity_fingerprint text NOT NULL, identity_rotated_at timestamptz);
CREATE INDEX agents_org_status_idx ON agents(organization_id,status);
CREATE TABLE agent_enrollment_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), token_hash text NOT NULL UNIQUE, created_by uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, used_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE module_definitions (id text PRIMARY KEY, name text NOT NULL, version text NOT NULL, category text NOT NULL, risk_class module_risk_class NOT NULL, supported_environments scope_environment[] NOT NULL, required_capabilities text[] NOT NULL, default_timeout_seconds integer NOT NULL CHECK(default_timeout_seconds > 0), input_schema jsonb NOT NULL, result_schema jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true);
