('performance.iperf3','Controlled performance test','0.1.0','performance','CONTROLLED_ACTIVE','{INTERNAL}','{iperf3}',120,'{"type":"object","additionalProperties":false}','{"type":"object"}');

CREATE TABLE analysis_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), module_id text NOT NULL REFERENCES module_definitions(id), asset_id uuid REFERENCES assets(id), scope_id uuid NOT NULL REFERENCES authorized_scopes(id), agent_id uuid NOT NULL REFERENCES agents(id), requested_by uuid NOT NULL REFERENCES users(id), parameters jsonb NOT NULL, normalized_target text NOT NULL, risk_class module_risk_class NOT NULL, status job_status NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), queued_at timestamptz, started_at timestamptz, completed_at timestamptz, timeout_at timestamptz NOT NULL, status_version integer NOT NULL DEFAULT 0, rejection_code text, CHECK(jsonb_typeof(parameters)='object'));
CREATE INDEX jobs_org_status_created_idx ON analysis_jobs(organization_id,status,created_at DESC);
CREATE INDEX jobs_agent_queue_idx ON analysis_jobs(agent_id,status,queued_at) WHERE status IN ('QUEUED','ASSIGNED');
CREATE TABLE schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), module_id text NOT NULL REFERENCES module_definitions(id), scope_id uuid NOT NULL REFERENCES authorized_scopes(id), agent_id uuid NOT NULL REFERENCES agents(id), frequency_seconds integer NOT NULL CHECK(frequency_seconds >= 60), enabled boolean NOT NULL DEFAULT true, next_run_at timestamptz NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), asset_id uuid REFERENCES assets(id), module_id text NOT NULL REFERENCES module_definitions(id), job_id uuid NOT NULL REFERENCES analysis_jobs(id), category text NOT NULL, status normalized_status NOT NULL, severity text NOT NULL, confidence confidence_level NOT NULL, title text NOT NULL, summary text NOT NULL, meaning text NOT NULL, impact text NOT NULL, suggested_action text NOT NULL, observed_at timestamptz NOT NULL, evidence_count integer NOT NULL DEFAULT 0, raw_reference text);
CREATE INDEX observations_asset_time_idx ON observations(organization_id,asset_id,observed_at DESC);
CREATE TABLE findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), asset_id uuid REFERENCES assets(id), source_observation_id uuid REFERENCES observations(id), category text NOT NULL, severity text NOT NULL, priority text NOT NULL, confidence confidence_level NOT NULL, title text NOT NULL, description text NOT NULL, remediation text NOT NULL, status text NOT NULL CHECK(status IN ('OPEN','ACKNOWLEDGED','RESOLVED','ACCEPTED','FALSE_POSITIVE')), first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, resolved_at timestamptz, resolved_by uuid REFERENCES users(id), risk_factors jsonb NOT NULL DEFAULT '{}');
CREATE INDEX findings_org_status_priority_idx ON findings(organization_id,status,priority,last_seen_at DESC);
CREATE TABLE evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), job_id uuid NOT NULL REFERENCES analysis_jobs(id), observation_id uuid REFERENCES observations(id), finding_id uuid REFERENCES findings(id), source text NOT NULL, content_type text NOT NULL, summary text NOT NULL, storage_key text, structured_data jsonb, checksum text, raw_access_required boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX evidence_finding_idx ON evidence(organization_id,finding_id,created_at);

CREATE TABLE vulnerabilities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), asset_id uuid NOT NULL REFERENCES assets(id), cve text, name text NOT NULL, description text NOT NULL, cvss_score numeric(3,1), cvss_version text, scanner_severity text NOT NULL, affected_service text, evidence_id uuid REFERENCES evidence(id), remediation text, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL);
CREATE TABLE vulnerability_enrichments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vulnerability_id uuid NOT NULL REFERENCES vulnerabilities(id) ON DELETE CASCADE, provider text NOT NULL, cve text, description text, cvss jsonb, reference_urls jsonb NOT NULL DEFAULT '[]', known_exploited boolean, date_added date, required_action text, due_date date, fetched_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, UNIQUE(vulnerability_id,provider));
CREATE TABLE traffic_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), asset_id uuid REFERENCES assets(id), job_id uuid NOT NULL REFERENCES analysis_jobs(id), source text NOT NULL, observation_type text NOT NULL, occurred_at timestamptz NOT NULL, summary jsonb NOT NULL, metadata_storage_key text);
CREATE INDEX traffic_org_time_idx ON traffic_observations(organization_id,occurred_at DESC);
CREATE TABLE pcap_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), uploaded_by uuid NOT NULL REFERENCES users(id), storage_key text NOT NULL UNIQUE, original_filename text NOT NULL, content_length bigint NOT NULL CHECK(content_length >= 0), checksum text NOT NULL, captured_at timestamptz, uploaded_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, deleted_at timestamptz, classification text NOT NULL DEFAULT 'SENSITIVE');
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), type text NOT NULL, title text NOT NULL, status text NOT NULL, parameters jsonb NOT NULL DEFAULT '{}', storage_key text, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE retention_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), category text NOT NULL CHECK(category IN ('PCAP','RAW_EVIDENCE','TRAFFIC_METADATA','JOB_OUTPUT','AUDIT','REPORTS')), retention_days integer CHECK(retention_days > 0), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,category));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid REFERENCES users(id), type text NOT NULL, title text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), actor_user_id uuid REFERENCES users(id), actor_agent_id uuid REFERENCES agents(id), event_type text NOT NULL, resource_type text, resource_id text, request_id text, outcome text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', previous_hash text, event_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_time_idx ON audit_events(organization_id,created_at DESC);

INSERT INTO permissions(name,description) VALUES
('assets.read','Read assets'),('assets.manage','Manage assets'),('scopes.read','Read authorized scopes'),('scopes.manage','Manage scopes'),('scopes.approve','Approve scopes'),('diagnostics.read','Read diagnostics'),('diagnostics.run','Run safe diagnostics'),('traffic.read','Read traffic analysis'),('pcap.upload','Upload PCAP'),('pcap.read','Read PCAP metadata'),('pcap.download','Download raw PCAP'),('pcap.delete','Delete PCAP'),('vulnerability.read','Read vulnerabilities'),('vulnerability.run','Run authorized vulnerability assessments'),('public_scan.run','Run modules against approved public scopes'),('findings.read','Read findings'),('findings.manage','Manage findings'),('evidence.raw.read','Read raw technical evidence'),('agents.read','Read agents'),('agents.manage','Manage agents'),('modules.read','Read modules'),('modules.manage','Manage modules'),('reports.read','Read reports'),('reports.create','Create reports'),('users.read','Read users'),('users.manage','Manage users'),('audit.read','Read audit events');

INSERT INTO roles(id,organization_id,name,system) VALUES
(gen_random_uuid(),NULL,'Owner',true),(gen_random_uuid(),NULL,'Administrator',true),(gen_random_uuid(),NULL,'Security Administrator',true),(gen_random_uuid(),NULL,'Security Analyst',true),(gen_random_uuid(),NULL,'Network Analyst',true),(gen_random_uuid(),NULL,'Operator',true),(gen_random_uuid(),NULL,'Viewer',true);

INSERT INTO role_permissions(role_id,permission_id)
SELECT r.id,p.id FROM roles r CROSS JOIN permissions p
WHERE r.system AND (
  (r.name='Owner' AND p.name<>'public_scan.run') OR
  (r.name='Administrator' AND p.name<>'public_scan.run') OR
  (r.name='Security Administrator' AND p.name IN ('assets.read','scopes.read','scopes.manage','scopes.approve','diagnostics.read','diagnostics.run','traffic.read','pcap.upload','pcap.read','pcap.download','pcap.delete','vulnerability.read','vulnerability.run','findings.read','findings.manage','evidence.raw.read','agents.read','agents.manage','modules.read','modules.manage','reports.read','reports.create','users.read','users.manage','audit.read')) OR
  (r.name='Security Analyst' AND p.name IN ('assets.read','scopes.read','diagnostics.read','diagnostics.run','traffic.read','pcap.upload','pcap.read','vulnerability.read','findings.read','findings.manage','reports.read','reports.create','agents.read','modules.read')) OR
  (r.name='Network Analyst' AND p.name IN ('assets.read','assets.manage','scopes.read','diagnostics.read','diagnostics.run','traffic.read','findings.read','reports.read','reports.create','agents.read','modules.read')) OR
  (r.name='Operator' AND p.name IN ('assets.read','scopes.read','diagnostics.read','diagnostics.run','findings.read','agents.read','modules.read','reports.read')) OR
  (r.name='Viewer' AND p.name IN ('assets.read','scopes.read','diagnostics.read','findings.read','agents.read','modules.read','reports.read'))
);
